$rows=json_decode(file_get_contents(__DIR__.'/media-sync.json'),true);$skipped=[];$updated=0;
function eu_attachment($a,$lang,$product){global $wpdb,$skipped;$file=$a['file'];if(!is_file(WP_CONTENT_DIR.'/uploads/'.$file)){$skipped[]=$file;return 0;}$ids=$wpdb->get_col($wpdb->prepare("SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key='_wp_attached_file' AND meta_value=%s",$file));foreach($ids as $id){if(!function_exists('pll_get_post_language')||pll_get_post_language($id)===$lang)return (int)$id;}if($ids)return (int)$ids[0];$id=wp_insert_attachment(['post_title'=>get_the_title($product),'post_mime_type'=>$a['mime'],'post_status'=>'inherit'],WP_CONTENT_DIR.'/uploads/'.$file);if(is_wp_error($id))throw new RuntimeException($id->get_error_message());update_post_meta($id,'_wp_attached_file',$file);if(is_array($a['metadata']))wp_update_attachment_metadata($id,$a['metadata']);update_post_meta($id,'_wp_attachment_image_alt',wp_strip_all_tags(get_the_title($product)));if(function_exists('pll_set_post_language'))pll_set_post_language($id,$lang);return $id;}
foreach($rows as $r){$id=$r['id'];if($r['thumbnail']){$aid=eu_attachment($r['thumbnail'],$r['lang'],$id);if($aid)update_post_meta($id,'_thumbnail_id',$aid);}if($r['gallery']!==null){$ids=[];foreach($r['gallery'] as $a){$aid=eu_attachment($a,$r['lang'],$id);if($aid)$ids[]=$aid;}if($ids)update_post_meta($id,'_product_image_gallery',implode(',',$ids));}clean_post_cache($id);$updated++;}echo json_encode(['updated_products'=>$updated,'missing_source_files'=>array_values(array_unique($skipped))],JSON_PRETTY_PRINT).PHP_EOL;
